package com.ynxweb4.shop;
import org.json.JSONArray;
final class NativeBusinessPolicy {
 static JSONArray scopes(String method,String path){if(!method.matches("GET|POST|PUT|DELETE")||!path.matches("/api/[A-Za-z0-9._:/-]{1,251}")||path.contains("//")||path.endsWith("/")||path.contains("/../")||path.contains("/./"))throw new SecurityException("Exact owned business path required");String route=path.substring(4);
  if(route.equals("/profile")&&(method.equals("GET")||method.equals("PUT"))||route.equals("/privacy/export")&&method.equals("GET")||route.equals("/privacy/delete")&&method.equals("POST"))return new JSONArray().put("account:read").put("shop:profile:write");
  if(route.equals("/cart")&&(method.equals("GET")||method.equals("PUT"))||route.equals("/orders")&&method.equals("POST")||route.equals("/orders/intent-lookup")&&method.equals("POST")||route.matches("/orders/[A-Za-z0-9][A-Za-z0-9._:-]{0,127}/pay-handoff")&&method.equals("POST")||route.matches("/orders/[A-Za-z0-9][A-Za-z0-9._:-]{0,127}/pay-handoff")&&method.equals("GET")||route.matches("/orders/[A-Za-z0-9][A-Za-z0-9._:-]{0,127}/confirm-payment")&&method.equals("POST"))return new JSONArray().put("account:read").put("shop:orders:write");
  if(route.equals("/orders")&&method.equals("GET")||route.matches("/orders/[A-Za-z0-9][A-Za-z0-9._:-]{0,127}")&&method.equals("GET")||route.matches("/orders/[A-Za-z0-9][A-Za-z0-9._:-]{0,127}/transition")&&method.equals("POST"))return NativeProductState.buyerScopes();
  if(route.equals("/ai/jobs")&&(method.equals("GET")||method.equals("POST"))||route.matches("/ai/jobs/[A-Za-z0-9][A-Za-z0-9._:-]{0,127}")&&(method.equals("GET")||method.equals("DELETE"))||route.matches("/ai/jobs/[A-Za-z0-9][A-Za-z0-9._:-]{0,127}/(?:run|decision)")&&method.equals("POST"))return NativeProductState.buyerScopes();throw new SecurityException("Owned Buyer business route required");}
}
